effect.shader:
// S_Glow Ultra-Smooth Implementation for Alight Motion

#define PI 3.14159265359
#define GOLDEN_ANGLE 2.3999632

float dither(vec2 uv) {
    return fract(sin(dot(uv, vec2(12.9898, 78.233))) * 43758.5453) * 0.004;
}

void main() {
    // Unifying to screen coordinates to fix squeeze/stretch issues
    vec2 uv = acScreenNorm.xy;
    float aspect = acScreenSize.x / acScreenSize.y;

    vec4 source = texture2DCv(inputImg.texture, uv);

    vec3 glowSum = vec3(0.0);
    float totalWeight = 0.0;

    int samples = int(quality);

    // Scaled weights based on dispersion (Match: 1.0, 1.4, 2.2)
    vec3 colorWeights = vec3(1.0, 1.0 + dispersion * 0.4, 1.0 + dispersion * 1.2);

    for(int i = 0; i < 128; i++) {
        if (i >= samples) break;

        float fraction = float(i) / float(samples);
        float angle = float(i) * GOLDEN_ANGLE;

        // Non-linear distribution: pow(fraction, 0.8)
        float dist = pow(fraction, 0.8); 

        vec2 dir = vec2(cos(angle), sin(angle));
        vec2 scale = vec2(widthX, widthY) * glowWidth * 0.12;
        scale.x /= aspect; // Correct for screen resolution to keep glow circular

        // True Gaussian weight
        float weight = exp(-dist * dist * 5.0);

        // Chromatic sampling
        vec2 uvR = uv + dir * dist * scale * colorWeights.r;
        vec2 uvG = uv + dir * dist * scale * colorWeights.g;
        vec2 uvB = uv + dir * dist * scale * colorWeights.b;

        // Sample and Threshold
        float r = max(texture2DCv(inputImg.texture, uvR).r - threshold, 0.0);
        float g = max(texture2DCv(inputImg.texture, uvG).g - threshold, 0.0);
        float b = max(texture2DCv(inputImg.texture, uvB).b - threshold, 0.0);

        glowSum += vec3(r, g, b) * weight;
        totalWeight += weight;
    }

    // Normalize, Apply Brightness, and Dither
    vec3 finalGlow = (glowSum / totalWeight) * brightness;
    finalGlow += dither(uv);

    // Screen Combine mode
    vec3 result = 1.0 - (1.0 - source.rgb) * (1.0 - finalGlow);

    // Subtle contrast adjustment
    result = pow(max(result, 0.0), vec3(0.95));

    vec4 finalColor = vec4(result, source.a);

    // Handle mixing - use original source as base to avoid global screen filling
    gl_FragColor = mix(source, finalColor, blend);
}
